// Name returns the Python member name.
func (e ARSupportValue) Name() string { return aRSupportValueNames[e] }

// Valid reports whether e is a defined member.
func (e ARSupportValue) Valid() bool { _, ok := aRSupportValueNames[e]; return ok }

// ARSupportValueFromValueOK mirrors `ARSupportValue.from_value` without the UNKNOWN fallback.
func ARSupportValueFromValueOK(value any) (ARSupportValue, bool) {
	switch v := value.(type) {
	case ARSupportValue:
		return v, v.Valid()
	case *ARSupportValue:
		if v != nil {
			return *v, v.Valid()
		}
	}
	if vstr := converters.RawToStr(value); vstr != nil {
		if m := ARSupportValue(*vstr); m.Valid() {
			return m, true
		}
		if m, ok := aRSupportValueByName[strings.ToUpper(*vstr)]; ok {
			return m, true
		}
	}
	var zero ARSupportValue
	return zero, false
}

// ARSupportValueFromValue mirrors `ARSupportValue.from_value`: unresolved values map to ARSupportValueUnknown.
func ARSupportValueFromValue(value any) ARSupportValue {
	if m, ok := ARSupportValueFromValueOK(value); ok {
		return m
	}
	return ARSupportValueUnknown
}
